tool_config.code:
import requests
import json
from datetime import datetime

def publish_alert(signal, analyst_response=None):
    # Merge analyst edits if any
    if analyst_response and analyst_response.get('action') == 'modify':
        signal.update(analyst_response.get('edits', {}))
    elif analyst_response and analyst_response.get('action') == 'reject':
        return {'status': 'rejected', 'reason': analyst_response.get('reason', 'Analyst rejected signal')}

    payload = {
        'signal_id': signal.get('signal_id'),
        'published_at': datetime.utcnow().isoformat(),
        'headline': signal.get('headline'),
        'urgency': signal.get('urgency'),
        'overall_signal': signal.get('overall_signal'),
        'confidence': signal.get('confidence'),
        'impact_score': signal.get('impact_score'),
        'summary': signal.get('summary'),
        'trade_ideas': signal.get('trade_ideas', []),
        'macro_narrative': signal.get('macro_narrative'),
        'key_risks': signal.get('key_risks', []),
        'analyst_approved': analyst_response is not None
    }

    results = {}

    # Slack webhook
    slack_url = 'https://hooks.slack.com/services/YOUR/SLACK/WEBHOOK'
    slack_message = {
        'text': f"*{payload['urgency'].upper()} MACRO ALERT* — {payload['headline']}",
        'attachments': [{
            'color': '#ff0000' if payload['urgency'] in ['high','critical'] else '#ffaa00',
            'fields': [
                {'title': 'Signal', 'value': payload['overall_signal'], 'short': True},
                {'title': 'Confidence', 'value': f"{payload['confidence']*100:.0f}%", 'short': True},
                {'title': 'Summary', 'value': payload['summary'], 'short': False}
            ]
        }]
    }
    try:
        r = requests.post(slack_url, json=slack_message, timeout=5)
        results['slack'] = {'status': r.status_code}
    except Exception as e:
        results['slack'] = {'error': str(e)}

    # Trading dashboard webhook
    dashboard_url = 'https://your-trading-dashboard.com/api/signals'
    try:
        r = requests.post(dashboard_url, json=payload, timeout=5)
        results['dashboard'] = {'status': r.status_code}
    except Exception as e:
        results['dashboard'] = {'error': str(e)}

    return {
        'status': 'published',
        'signal_id': payload['signal_id'],
        'published_at': payload['published_at'],
        'channels': results,
        'payload': payload
    }
